      (it.pageUrls||[]).forEach(function(p){b+='<a class="btn" href="'+p+'" target="_blank" rel="noopener">\u4E66\u9875</a>'});
      var tags=(it.srcs||[]).map(function(s){return '<span class="tag">'+esc(s)+'</span>'}).join('');
      var row=document.createElement('div');row.className='item';
      row.innerHTML='<div class="t"><b>'+esc(it.title)+'</b><span>'+esc([it.author,it.extra].filter(Boolean).join(' \xB7 '))+'</span>'+(tags?'<div class="tags">'+tags+'</div>':'')+'</div>'+b;
      out.appendChild(row);
